from PIL import Image
import numpy as np
img = Image.open('/app/board.png')
arr = np.array(img)
# Find first non-border pixel
border = np.array([49,46,43])
# scan along middle row
mid = 387
row = arr[mid]
for x in range(arr.shape[1]):
    if not np.array_equal(row[x], border):
        print('left edge:', x); break
for x in range(arr.shape[1]-1, -1, -1):
    if not np.array_equal(row[x], border):
        print('right edge:', x); break
col = arr[:,mid]
for y in range(arr.shape[0]):
    if not np.array_equal(col[y], border):
        print('top edge:', y); break
for y in range(arr.shape[0]-1, -1, -1):
    if not np.array_equal(col[y], border):
        print('bot edge:', y); break
